SELECT /*LGVATT50060.retrieveEmpULWarning*/ em.organization_id AS employee_org ,em.employee_number AS employee_no ,em.full_name_local AS employee_name ,em.grade_title AS employee_grade ,em.attribute10 AS actual_shift_code ,em.assignment_category AS employee_category ,TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') AS date_hire_subsidiary ,TO_CHAR(EU.START_DATE, 'DD/MM/YYYY') as START_DATE ,TO_CHAR(EU.END_DATE, 'DD/MM/YYYY') as END_DATE ,EU.TOTAL_DAYS ,EU.SEND_EMAIL_FLAG ,EU.MANAGER_NO_1 ,EU.MANAGER_EMAIL_1 ,(select full_name_local from emp_master where employee_number = eu.MANAGER_NO_1) as MANAGER_NAME_1 ,EU.MANAGER_NO_2 ,EU.MANAGER_EMAIL_2 ,EU.MANAGER_NO_3 ,EU.MANAGER_EMAIL_3 ,EU.NOTE ,EU.REMARK ,(select local_language_full_name from lgcom_user_m where application_user_id = eu.creation_user_id) as CREATION_USER_ID ,TO_CHAR(EU.CREATION_DATE, 'DD/MM/YYYY hh24:mi') as CREATION_DATE ,(select local_language_full_name from lgcom_user_m where application_user_id = eu.LAST_UPDATE_USER_ID) as LAST_UPDATE_USER_ID ,TO_CHAR(EU.LAST_UPDATE_DATE, 'DD/MM/YYYY hh24:mi') as LAST_UPDATE_DATE FROM TB_ATT_EMP_UL_WARNING EU, emp_master em WHERE em.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND eu.employee_no = em.employee_number AND eu.START_DATE >= to_date(#{atendanceStartDate}, 'dd/mm/yyyy') AND eu.END_DATE <= to_date(#{atendanceEndDate}, 'dd/mm/yyyy')
AND eu.manager_no_1 = #{managerNo}
AND em.attribute10 = #{shiftCode}
AND em.assignment_category = #{categoryTitle}
AND em.organization_id = #{orgId}
AND em.employee_number = UPPER(#{empNo})
AND UPPER(em.full_name_local) LIKE '%' || UPPER(#{empName}) || '%'
AND EU.SEND_EMAIL_FLAG = #{sendEmailFlag}
ORDER BY eu.employee_no, eu.START_DATE asc

mapper.insert:
INSERT INTO /* LGVATT50060.createExcelDownloadData */ XXLGE_EXPORT_INFO (SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5 , ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8 , ATTRIBUTE9, ATTRIBUTE10 , ATTRIBUTE11, ATTRIBUTE12, ATTRIBUTE13, ATTRIBUTE14, ATTRIBUTE15 , ATTRIBUTE16, ATTRIBUTE17, ATTRIBUTE18) SELECT AA.* FROM ( SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 1 AS ORDER_BY , 'KO16KSC5601' , 'Employee No' AS EMPLOYEE_NO , 'Employee Name' AS EMPLOYEE_NAME_LOCAL , 'Employee Grade' AS EMPLOYEE_GRADE , 'Employee Category' AS EMPLOYEE_CATEGORY , 'Date Hire Subsidiary' AS DATE_HIRE_SUBSIDIARY , 'Start Date' AS START_DATE , 'End Date' AS END_DATE , 'Total Days' AS TOTAL_DAYS , 'Manager No 1' AS MANAGER_NO_1 , 'Manager Email 1' AS MANAGER_EMAIL_1 , 'Manager Name 1' AS MANAGER_NAME_1 , 'Note' AS NOTE , 'Remark' AS REMARK , 'Send Email Flag' AS SEND_EMAIL_FLAG , 'Creation User Id' AS CREATION_USER_ID , 'Creation Date' AS CREATION_DATE , 'Last Update User Id' AS LAST_UPDATE_USER_ID , 'Last Update Date' AS LAST_UPDATE_DATE
FROM DUAL UNION ALL
SELECT #{sessionId} ,#{USER_SESSION.applicationUserId} ,SYSDATE ,2 AS ORDER_BY ,'KO16KSC5601' ,em.employee_number AS employee_no ,em.full_name_local AS employee_name ,em.grade_title AS employee_grade ,em.assignment_category AS employee_category ,TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') AS date_hire_subsidiary ,TO_CHAR(EU.START_DATE, 'DD/MM/YYYY') as START_DATE ,TO_CHAR(EU.END_DATE, 'DD/MM/YYYY') as END_DATE ,TO_CHAR(EU.TOTAL_DAYS) ,EU.MANAGER_NO_1 ,EU.MANAGER_EMAIL_1 ,(select full_name_local from emp_master where employee_number = eu.MANAGER_NO_1) as MANAGER_NAME_1 ,EU.NOTE ,EU.REMARK ,TO_CHAR(EU.SEND_EMAIL_FLAG) ,(select local_language_full_name from lgcom_user_m where application_user_id = eu.creation_user_id) as CREATION_USER_ID ,TO_CHAR(EU.CREATION_DATE, 'DD/MM/YYYY hh24:mi') as CREATION_DATE ,(select local_language_full_name from lgcom_user_m where application_user_id = eu.LAST_UPDATE_USER_ID) as LAST_UPDATE_USER_ID ,TO_CHAR(EU.LAST_UPDATE_DATE, 'DD/MM/YYYY hh24:mi') as LAST_UPDATE_DATE FROM TB_ATT_EMP_UL_WARNING EU, emp_master em WHERE em.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} AND eu.employee_no = em.employee_number AND eu.START_DATE >= to_date(#{atendanceStartDate}, 'dd/mm/yyyy') AND eu.END_DATE <= to_date(#{atendanceEndDate}, 'dd/mm/yyyy')
AND eu.manager_no_1 = #{managerNo}
AND em.attribute10 = #{shiftCode}
AND em.assignment_category = #{categoryTitle}
AND em.organization_id = #{orgId}
AND em.employee_number = UPPER(#{empNo})
AND UPPER(em.full_name_local) LIKE '%' || UPPER(#{empName}) || '%'
AND EU.SEND_EMAIL_FLAG = #{sendEmailFlag}
) AA ORDER BY ORDER_BY, AA.EMPLOYEE_NO asc

