UPDATE /*LGVATT50060.cancelSendEmail*/
       TB_ATT_EMP_UL_WARNING 
SET    SEND_EMAIL_FLAG                 = #{sendEmailFlag}             
     , last_update_user_id             = #{applicationUserId}            					/* 최종수정사용자아이디 */
     , last_update_date                = sysdate                 							/* 최종수정일자 */
WHERE  employee_no = #{employeeNo}
   AND to_char(START_DATE, 'dd/mm/yyyy') = #{startDate} 
   AND to_char(END_DATE, 'dd/mm/yyyy')   = #{endDate}

UPDATE /*LGVATT50060.updateEmpUlWarning*/
       TB_ATT_EMP_UL_WARNING 
SET    REMARK                 = #{remark}             
     , last_update_user_id             = #{applicationUserId}            					/* 최종수정사용자아이디 */
     , last_update_date                = sysdate                 							/* 최종수정일자 */
WHERE  employee_no = #{employeeNo}
   AND to_char(START_DATE, 'dd/mm/yyyy') = #{startDate} 
   AND to_char(END_DATE, 'dd/mm/yyyy')   = #{endDate}
